// Some portions generated by Claude
import type { CSSProperties, Ref } from "react";
import type { SparqlValue } from "./explorer-types.ts";
import { compactTerm } from "./graph-terms.ts";
import type { GraphEdge, GraphNode } from "./graph-types.ts";
import { nodeVisual } from "./graph-visuals.ts";
import { Icon } from "./icons.tsx";
import { languageRank } from "./rdf-vocabulary.ts";
import type { StatementCard } from "./statement-details.ts";
import type { StatementDetails } from "./use-statement-details.ts";

export type StatementDetailsCardProps = {
  edge: GraphEdge;
  source: GraphNode | undefined;
  target: GraphNode | undefined;
  details: StatementDetails;
  labelOf: (iri: string) => string;
  /** The label language preferences: the description in the first available language is shown. */
  languages: readonly string[];
  exploreHref: (iri: string) => string;
  cardRef: Ref<HTMLElement>;
  onClose: () => void;
  onCopy: (text: string) => void;
  onFollow: (nodeId: string) => void;
  onAdd: (card: StatementCard) => void;
};

const CARD_KIND: Record<StatementCard["kind"], string> = {
  reifier: "Reifier",
  reification: "rdf:Statement",
  reference: "Refers to it",
};

function valueText(value: SparqlValue, labelOf: (iri: string) => string): string {
  if (value.type === "uri") return labelOf(value.value);
  if (value.type === "bnode") return "Blank node";
  // SPARQL JSON writes an RDF 1.2 triple term as {"type": "triple", "value": {subject, predicate, object}}.
  if ((value.type as string) === "triple") {
    const triple = value.value as unknown as { subject?: SparqlValue; predicate?: SparqlValue; object?: SparqlValue };
    const part = (term?: SparqlValue) => (term ? valueText(term, labelOf) : "?");
    return `<<( ${part(triple.subject)} ${part(triple.predicate)} ${part(triple.object)} )>>`;
  }
  return value.value;
}

function NodeButton({ node, fallback, onFollow }: { node: GraphNode | undefined; fallback: string; onFollow: (id: string) => void }) {
  if (!node) return <span>{compactTerm(fallback, 40)}</span>;
  return (
    <button
      type="button"
      className="node-details-link"
      style={{ "--node-color": nodeVisual(node).stroke } as CSSProperties}
      onClick={() => onFollow(node.id)}
    >
      {node.kind === "literal" ? (node.termValue ?? node.label) : node.label}
    </button>
  );
}

function IriList({ label, iris, labelOf }: { label: string; iris: string[]; labelOf: (iri: string) => string }) {
  if (!iris.length) return null;
  return (
    <div className="node-details-row">
      <dt>{label}</dt>
      <dd>
        {iris.map((iri) => (
          <span key={iri} className="node-details-value" title={iri}>
            {labelOf(iri)}
          </span>
        ))}
      </dd>
    </div>
  );
}

/**
 * The selected edge's card over the canvas: the statement, what its predicate means and how often it is used, and a
 * card for each resource that says something about the statement (reifiers, rdf:Statement reifications, references).
 */
export function StatementDetailsCard({
  edge,
  source,
  target,
  details,
  labelOf,
  languages,
  exploreHref,
  cardRef,
  onClose,
  onCopy,
  onFollow,
  onAdd,
}: StatementDetailsCardProps) {
  const { info, uses, cards } = details;
  const description = info?.descriptions
    .slice()
    .sort((left, right) => languageRank(left.language, [...languages]) - languageRank(right.language, [...languages]))[0];
  return (
    <aside
      ref={cardRef}
      className="node-details statement-details"
      aria-label={`Statement ${edge.label}`}
      tabIndex={-1}
      onClick={(event) => event.stopPropagation()}
      onPointerDown={(event) => event.stopPropagation()}
      onWheel={(event) => event.stopPropagation()}
    >
      <header className="node-details-header">
        <div>
          <p className="node-details-kind">Statement</p>
          <h3>{edge.label}</h3>
        </div>
        <button
          className="workbench-action workbench-action--ghost workbench-action--icon"
          type="button"
          aria-label="Close details"
          title="Close details"
          onClick={onClose}
        >
          <Icon name="close" />
        </button>
      </header>
      <p className="statement-details-triple">
        <NodeButton node={source} fallback={edge.source} onFollow={onFollow} />
        <span aria-hidden="true">→</span>
        <NodeButton node={target} fallback={edge.target} onFollow={onFollow} />
      </p>
      <div className="node-details-identifier">
        <code title={edge.predicate}>{edge.predicate}</code>
        <button
          className="workbench-action workbench-action--ghost workbench-action--icon"
          type="button"
          aria-label="Copy predicate"
          title="Copy predicate"
          onClick={() => onCopy(edge.predicate)}
        >
          <Icon name="copy" />
        </button>
        <a
          className="workbench-action workbench-action--ghost workbench-action--icon"
          href={exploreHref(edge.predicate)}
          aria-label="Explore the predicate"
          title="Explore the predicate"
        >
          <Icon name="explore" />
        </a>
      </div>
      {description ? <p className="statement-details-description">{description.text}</p> : null}
      {info && (info.domain.length || info.range.length || info.superProperties.length || info.inverse.length || uses) ? (
        <dl className="node-details-body">
          <IriList label="Domain" iris={info.domain} labelOf={labelOf} />
          <IriList label="Range" iris={info.range} labelOf={labelOf} />
          <IriList label="Sub-property of" iris={info.superProperties} labelOf={labelOf} />
          <IriList label="Inverse of" iris={info.inverse} labelOf={labelOf} />
          {uses ? (
            <div className="node-details-row">
              <dt>Used in</dt>
              <dd>
                <span className="node-details-value">
                  {uses.count.toLocaleString()}
                  {uses.atLeast ? "+" : ""} {uses.count === 1 && !uses.atLeast ? "statement" : "statements"}
                </span>
              </dd>
            </div>
          ) : null}
        </dl>
      ) : null}
      {details.status === "loading" ? <p className="statement-details-note" aria-live="polite">Loading…</p> : null}
      {details.status === "failed" ? <p className="statement-details-note">The statement's details could not be loaded.</p> : null}
      {details.status === "ready" && details.unnamed ? (
        <p className="statement-details-note">A blank node takes part, so what is said about this statement cannot be looked up.</p>
      ) : null}
      {cards.length ? (
        <section className="statement-cards" aria-label="About this statement">
          <h4>About this statement</h4>
          {cards.map((card) => {
            const name = valueText(card.about, labelOf);
            // The card's name is the resource's label; a row that only repeats it says nothing new.
            const rows = card.rows.filter((row) => !row.value || row.value.type === "uri" || row.value.value !== name);
            return (
              <article key={`${card.kind} ${card.about.type} ${card.about.value}`} className="statement-card" data-kind={card.kind}>
                <header>
                  <small>{CARD_KIND[card.kind]}</small>
                  <strong title={card.about.type === "uri" ? card.about.value : undefined}>{name}</strong>
                  <button
                    className="workbench-action workbench-action--ghost workbench-action--icon"
                    type="button"
                    aria-label={`Add ${name} to the graph`}
                    title="Add to the graph"
                    disabled={card.about.type !== "uri" && !card.rows.some((row) => row.value && (row.value.type as string) !== "triple")}
                    onClick={() => onAdd(card)}
                  >
                    <Icon name="expand" />
                  </button>
                </header>
                {rows.length ? (
                  <dl>
                    {rows.map((row, index) => (
                      <div key={`${row.property} ${index}`} className="node-details-row">
                        <dt title={row.property}>{labelOf(row.property)}</dt>
                        <dd>
                          {row.value ? (
                            <span className="node-details-value" title={row.value.type === "uri" ? row.value.value : undefined}>
                              {valueText(row.value, labelOf)}
                              {row.value["xml:lang"] ? <small>{row.value["xml:lang"]}</small> : null}
                            </span>
                          ) : (
                            <span className="node-details-value">this statement</span>
                          )}
                        </dd>
                      </div>
                    ))}
                  </dl>
                ) : null}
              </article>
            );
          })}
        </section>
      ) : null}
    </aside>
  );
}
